// 3 days/week, ~60 min sessions, moderate intensity. Equipment: Resistance bands, Barbell, rack & bench, Dual adjustable pulley (cable), Dumbbells & bench, Kettlebells, Lat pulldown station, Pull-up bar.
# Week 1
// Estimated ~52 min
## Full Body A
// Brace, sit between your hips, knees track over toes.
Squat, Barbell / 3x8 / 20kg / 120s / progress: lp(2.5kg, 1, 0, 10%, 3, 0)
// Shoulder blades pinched, bar to lower chest, feet planted.
Bench Press, Barbell / 3x8 / 20kg / 120s / progress: lp(2.5kg, 1, 0, 10%, 3, 0)
// Low pulley, sit tall, pull handles to your ribs.
Seated Row, Cable / 3x8 / 20kg / 120s / progress: dp(2.5kg, 8, 12)
// Low back pressed into the floor, extend opposite arm and leg.
Dead Bug, Bodyweight / 3x8 / 0kg / 75s / warmup: none / progress: custom(maxReps: 15) {~
  if (completedReps >= reps && reps[ns] < state.maxReps) {
    reps += 1
  }
~}
// Low pulley, elbows still, squeeze at the top.
Bicep Curl, Cable / 3x10 / 7.5kg / 75s / warmup: none / progress: dp(2.5kg, 10, 14)
// Lead with the elbows, raise to shoulder height.
Lateral Raise, Dumbbell / 3x10 / 4kg / 75s / warmup: none / progress: dp(2kg, 10, 14)
// On a step if you can, pause at the top.
Standing Calf Raise, Dumbbell / 3x10 / 10kg / 75s / warmup: none / progress: dp(2kg, 10, 14)

// Estimated ~52 min
## Full Body B
// Bar over mid-foot, flat back, push the floor away.
Deadlift, Barbell / 3x8 / 40kg / 120s / progress: lp(5kg, 1, 0, 10%, 3, 0)
// Seated or standing, press up without arching your back.
Shoulder Press, Dumbbell / 3x8 / 8kg / 120s / progress: dp(2kg, 8, 12)
// Thighs under the pad, pull the bar to your upper chest.
Lat Pulldown, Cable / 3x8 / 25kg / 120s / progress: dp(2.5kg, 8, 12)
// Step back, front shin vertical, push through the front heel.
Reverse Lunge, Dumbbell / 3x10 / 6kg / 75s / warmup: none / progress: dp(2kg, 10, 14)
// Pulley high, elbows pinned, push down to lockout.
Triceps Pushdown, Cable / 3x10 / 12.5kg / 75s / warmup: none / progress: dp(2.5kg, 10, 14)
// Rope at face height, pull to your forehead, elbows high.
Standing Row Rear Delt With Rope, Cable / 3x10 / 7.5kg / 75s / warmup: none / progress: dp(2.5kg, 10, 14)
// Pulley high, kneel with the rope, crunch ribs toward hips.
Cable Crunch, Cable / 3x10 / 15kg / 75s / warmup: none / progress: dp(2.5kg, 10, 14)

// Estimated ~52 min
## Full Body C
// Brace, sit between your hips, knees track over toes.
Squat, Barbell / 3x8 / 20kg / 120s
// Bench at ~30°, press up and slightly back.
Incline Bench Press, Dumbbell / 3x8 / 8kg / 120s / progress: dp(2kg, 8, 12)
// Hinge to ~45°, pull the bar to your belly button.
Bent Over Row, Barbell / 3x8 / 20kg / 120s / progress: lp(2.5kg, 1, 0, 10%, 3, 0)
// Upper back on the bench, chin tucked, squeeze at the top.
Hip Thrust, Barbell / 3x10 / 30kg / 75s / warmup: none / progress: dp(2.5kg, 10, 14)
// Pulley high, kneel with the rope, crunch ribs toward hips.
Cable Crunch, Cable / 3x10 / 15kg / 75s / warmup: none
// Palms facing each other the whole time.
Hammer Curl, Dumbbell / 3x10 / 6kg / 75s / warmup: none / progress: dp(2kg, 10, 14)
// One dumbbell overhead with both hands, lower behind your head.
Triceps Extension, Dumbbell / 3x10 / 6kg / 75s / warmup: none / progress: dp(2kg, 10, 14)
